523	    interceptors = this.applyInstanceDecoratorIfRegistered<NestInterceptor>(
524	      ...interceptors,
525	    );
526	    this.config.useGlobalInterceptors(...interceptors);
527	    interceptors.forEach(item =>
528	      this.graphInspector.insertOrphanedEnhancer({
529	        subtype: 'interceptor',
530	        ref: item,
531	      }),
532	    );
533	    return this;
534	  }
535	
536	  public useGlobalGuards(...guards: CanActivate[]): this {
537	    guards = this.applyInstanceDecoratorIfRegistered<CanActivate>(...guards);
538	    this.config.useGlobalGuards(...guards);
539	    guards.forEach(item =>
540	      this.graphInspector.insertOrphanedEnhancer({
541	        subtype: 'guard',
542	        ref: item,
543	      }),
544	    );
