9	/**
10	 * Base class for HTTP platform adapters (see `ExpressAdapter` and
11	 * `FastifyAdapter` for reference implementations).
12	 *
13	 * It implements the {@link HttpServer} contract that the Nest core relies on,
14	 * and that interface is where each method's calling conventions are
15	 * documented: when the core invokes it, with which arguments, and what it
16	 * expects back. This class only adds:
17	 *
18	 * - default implementations that delegate to the wrapped framework
19	 *   `instance` (`use()`, the HTTP-verb methods, `listen()`) or are inert
20	 *   (`init()`, `normalizePath()`, `mapException()`, `beforeClose()`, the
21	 *   `setOn*Hook()` setters);
22	 * - storage for the native server (`httpServer`) and the framework instance
23	 *   (`instance`), with their accessors;
24	 * - the introspection hooks used by instrumentation tooling.
25	 *
26	 * Every remaining {@link HttpServer} member is declared abstract here, even
27	 * the ones the interface marks optional, so subclasses cannot forget them.
28	 * `setBaseViewsDir()`, `useBodyParser()` and `isRouteOrderSensitive()` are
29	 * not declared on this class; implement them when the platform supports
30	 * them (see {@link HttpServer} for what the core does when they are absent).
31	 *
32	 * Keep in mind that the core also reads and writes properties of the request
33	 * object (`body`, `params`, `query`, `headers`, ...), that Server-Sent Events
34	 * write directly to the Node.js response, and that `app.listen()` and the
35	 * WebSocket adapters use the value returned by
36	 * {@link AbstractHttpAdapter.getHttpServer} as a Node.js `net.Server`; see the
37	 * {@link HttpServer} documentation for details.
38	 *
39	 * @typeParam TServer - Type of the native HTTP server stored in `httpServer`
40	 * (e.g. `http.Server | https.Server`).
41	 * @typeParam TRequest - Type of the framework request object.
42	 * @typeParam TResponse - Type of the framework response object.
43	 *
44	 * @see [HTTP adapter](https://docs.nestjs.com/faq/http-adapter)
45	 *
46	 * @publicApi
47	 */
48	export abstract class AbstractHttpAdapter<
49	  TServer = any,
50	  TRequest = any,
51	  TResponse = any,
52	> implements HttpServer<TRequest, TResponse> {
53	  /**
54	   * Native HTTP server created by {@link AbstractHttpAdapter.initHttpServer}
55	   * and returned by {@link AbstractHttpAdapter.getHttpServer}.
56	   */
57	  protected httpServer: TServer;
58	  /**
59	   * Callback registered through
60	   * {@link AbstractHttpAdapter.setOnRouteTriggered}, if any.
61	   */
62	  protected onRouteTriggered:
63	    ((requestMethod: RequestMethod, path: string) => void) | undefined;
64	
65	  /**
