import {
  type CallHandler,
  type ExecutionContext,
  Injectable,
  type NestInterceptor,
} from '@nestjs/common';
import { defer, type Observable } from 'rxjs';
import { mergeAll } from 'rxjs/operators';
import { RequestContextHost } from './request-context.host.js';

/**
 * Global interceptor installed by {@link RequestContextModule}. It locates
 * the snapshot that the request hook attached to the platform request and
 * subscribes to the handler chain inside that snapshot's async-local context,
 * so `RequestContextHost.current()` stays available in continuations even
 * when the request object is not passed around.
 */
@Injectable()
export class RequestContextInterceptor implements NestInterceptor {
  constructor(private readonly contextHost: RequestContextHost) {}

  public intercept(
    context: ExecutionContext,
    next: CallHandler,
  ): Observable<unknown> {
    const httpHost = context.switchToHttp();
    const snapshot = this.contextHost.getForRequest(httpHost.getRequest());

    // `defer` runs when the router subscribes; `run` restores the context for
    // the synchronous subscription, and Nest's AsyncResource-bound handler
    // chain propagates it into awaited continuations.
    return defer(() =>
      snapshot
        ? this.contextHost.runWithContext(snapshot, () => next.handle())
        : next.handle(),
    ).pipe(mergeAll());
  }
}

