import {
  type CallHandler,
  type ExecutionContext,
  Injectable,
  type NestInterceptor,
} from '@nestjs/common';
import type { Observable } from 'rxjs';
import { RequestContextHost } from './request-context.host.js';
import type { RequestContextSnapshot } from './request-context-snapshot.js';

/**
 * Global interceptor installed by {@link RequestContextModule}. It locates
 * the snapshot that the request hook attached to the platform request and
 * runs the handler (and everything downstream of it) inside that snapshot's
 * async-local context, so `RequestContextHost.current()` stays available in
 * continuations even when the request object is not passed around.
 */
@Injectable()
export class RequestContextInterceptor implements NestInterceptor {
  constructor(private readonly contextHost: RequestContextHost) {}

  public intercept(
    context: ExecutionContext,
    next: CallHandler,
  ): Observable<unknown> | Promise<Observable<unknown>> {
    const httpHost = context.switchToHttp();
    const request = httpHost.getRequest();
    const snapshot = this.contextHost.getForRequest(request);

    if (!snapshot) {
      // The module is installed but no snapshot was attached (e.g. custom
      // adapter without request-hook support): behave transparently.
      return next.handle();
    }

    const stream$ = next.handle();
    return this.contextHost.runWithContext(snapshot, () => stream$);
  }
}

/**
 * Type helper kept for documentation/consumers that want to narrow the
 * interceptor's dependency in tests.
 */
export type { RequestContextSnapshot };

