import {
  ArgumentsHost,
  Catch,
  ExceptionFilter,
  HttpStatus,
  Module,
} from '@nestjs/common';
import { APP_FILTER } from '@nestjs/core';
import { RequestContextModule } from '@nestjs/core';
import { AppController } from './app.controller.js';
import { ContextRecordsStore } from './context-records.store.js';

/**
 * Domain error thrown by the probe when `fail=filtered`. It is converted to
 * an HTTP response by an application-registered exception filter, exercising
 * the requirement that snapshots terminate when a controller error is
 * transformed by an existing exception filter.
 */
export class FilteredProbeError extends Error {
  constructor(public readonly marker: string) {
    super(`filtered probe error: ${marker}`);
    this.name = 'FilteredProbeError';
  }
}

@Catch(FilteredProbeError)
export class FilteredProbeExceptionFilter implements ExceptionFilter {
  public catch(exception: FilteredProbeError, host: ArgumentsHost): void {
    const response = host.switchToHttp().getResponse();
    const expressResponse = response as {
      status?: (code: number) => unknown;
      json?: (body: unknown) => void;
      statusCode?: number;
      send?: (body: unknown) => void;
      code?: (status: number) => unknown;
    };

    const body = {
      filtered: true,
      marker: exception.marker,
    };

    if (typeof expressResponse.status === 'function') {
      // Express
      expressResponse.status(HttpStatus.UNPROCESSABLE_ENTITY)!.json?.(body);
    } else if (typeof expressResponse.code === 'function') {
      // Fastify
      expressResponse.code(HttpStatus.UNPROCESSABLE_ENTITY)!.send?.(body);
    }
  }
}

@Module({
  imports: [RequestContextModule.forRoot()],
  controllers: [AppController],
  providers: [
    ContextRecordsStore,
    {
      provide: APP_FILTER,
      useClass: FilteredProbeExceptionFilter,
    },
  ],
})
export class AppModule {}

