  imports: [RequestContextModule.forRoot()],
  controllers: [AppController],
  providers: [
    ContextRecordsStore,
    {
      provide: APP_FILTER,
      useClass: FilteredProbeExceptionFilter,
    },
  ],
})
export class AppModule {}

