import { Controller, Get, Injectable, Module } from '@nestjs/common';
import { NestFactory, RequestContextHost, RequestContextModule } from '@nestjs/core';

@Injectable()
class AlsProbe {
  constructor(private readonly host: RequestContextHost) {}
  async check() {
    const before = this.host.current()?.id;
    await new Promise(r => setTimeout(r, 30));
    await Promise.resolve();
    const after = this.host.current()?.id;
    return { before, after, same: before === after && !!before };
  }
}
@Controller()
class AlsController {
  constructor(private readonly probe: AlsProbe) {}
  @Get('als')
  als() { return this.probe.check(); }
}
@Module({
  imports: [RequestContextModule.forRoot()],
  controllers: [AlsController],
  providers: [AlsProbe],
})
class AlsModule {}

