1	import { AsyncLocalStorage } from 'async_hooks';
2	import { AbstractHttpAdapter } from '../adapters/http-adapter.js';
3	import { HttpAdapterHost } from '../helpers/http-adapter-host.js';
4	import {
5	  Injectable,
6	  OnApplicationShutdown,
7	  OnModuleInit,
8	} from '@nestjs/common';
9	import { REQUEST_CONTEXT_SNAPSHOT } from './request-context.constants.js';
10	import { RequestContextSnapshot } from './request-context-snapshot.js';
11	
12	/**
13	 * Per-application registry that binds {@link RequestContextSnapshot}
14	 * instances to HTTP requests and drives their lifecycle.
15	 *
16	 * A snapshot is created at the very beginning of every request (through the
17	 * adapter request hook) and terminated exactly once when the underlying
18	 * response emits `finish` (response completed, including error responses
19	 * produced by exception filters) or `close` without having finished (client
20	 * aborted). Termination is idempotent on the snapshot itself, so framework
21	 * quirks that surface both events can never double-terminate it.
22	 *
23	 * The host is an application-scoped singleton provided by
24	 * {@link RequestContextModule}; each Nest application therefore gets its own
25	 * instance and its own set of snapshots. During application shutdown it
26	 * awaits every snapshot's post-response callbacks before the shutdown
27	 * sequence completes.
28	 *
29	 * @publicApi
30	 */
31	@Injectable()
32	export class RequestContextHost
33	  implements OnModuleInit, OnApplicationShutdown
34	{
35	  private readonly asyncLocalStorage =
36	    new AsyncLocalStorage<RequestContextSnapshot>();
37	
38	  /**
39	   * Every snapshot created by this application instance. Snapshots are only
40	   * added, never replaced, so records can never be replayed or lost while the
41	   * application is alive.
42	   */
43	  private readonly snapshots = new Set<RequestContextSnapshot>();
44	
45	  /**
46	   * Raw responses that already have their terminal listeners attached.
47	   */
48	  private readonly attachedResponses = new WeakSet<object>();
49	
50	  constructor(private readonly httpAdapterHost: HttpAdapterHost) {}
51	
52	  /**
53	   * Installs the request-entry hook on the underlying HTTP adapter. The hook
54	   * is read by the built-in adapters per incoming request, so registering it
55	   * during module initialization (after the adapter itself was constructed)
56	   * still takes effect for every request.
57	   */
58	  public onModuleInit(): void {
59	    const adapter = this.httpAdapterHost.httpAdapter;
60	    adapter?.setOnRequestHook?.(
61	      (request: unknown, response: unknown, done: () => void) => {
62	        try {
63	          this.attachToRequest(request, response, adapter);
64	        } finally {
65	          done();
66	        }
67	      },
68	    );
69	  }
70	
71	  /**
72	   * Runs `callback` with `snapshot` set as the current async context, so
73	   * request-scoped call trees can retrieve it via {@link current}.
74	   */
75	  public runWithContext<T>(
76	    snapshot: RequestContextSnapshot,
77	    callback: () => T,
78	  ): T {
79	    return this.asyncLocalStorage.run(snapshot, callback);
80	  }
81	
82	  /**
83	   * Returns the snapshot associated with the current async context, if code
84	   * is running (synchronously or in ALS-propagated continuations) within a
85	   * request handled by {@link RequestContextModule}.
86	   */
87	  public current(): RequestContextSnapshot | undefined {
88	    return this.asyncLocalStorage.getStore();
89	  }
90	
91	  /**
92	   * Returns the snapshot previously attached to a platform request object
93	   * (Express request or Fastify request wrapper), checking the raw request as
94	   * a fallback.
95	   */
96	  public getForRequest(request: unknown): RequestContextSnapshot | undefined {
97	    if (!request || typeof request !== 'object') {
98	      return undefined;
99	    }
100	    const carrier = request as Record<symbol, unknown>;
101	    const fromWrapper = carrier[REQUEST_CONTEXT_SNAPSHOT];
102	    if (fromSnapshot(fromWrapper)) {
103	      return fromWrapper;
104	    }
105	    const raw = (request as { raw?: unknown }).raw;
106	    const fromRaw = (raw as Record<symbol, unknown> | undefined)?.[
107	      REQUEST_CONTEXT_SNAPSHOT
108	    ];
109	    return fromSnapshot(fromRaw) ? fromRaw : undefined;
110	  }
