8	import { RequestContext, type RequestContextSnapshot } from '@nestjs/core';
9	import { ContextRecordsStore } from './context-records.store.js';
10	import { FilteredProbeError } from './filtered-probe.error.js';
11	
12	/**
13	 * Probe controller backing the request-context snapshot integration tests.
14	 *
15	 * - `GET /context-probe?marker=...` stores the marker in the request
16	 *   snapshot, registers one or more post-response callbacks (each parked
17	 *   behind a per-registration gate until tests release it) and completes the
18	 *   response.
19	 * - `GET /context-records` reads back every registration with its current
20	 *   lifecycle state.
21	 * - `GET /release-gates[?callbackId=...]` releases pending callback gates.
22	 */
23	@Controller()
24	export class AppController {
25	  constructor(private readonly records: ContextRecordsStore) {}
26	
27	  @Get('context-probe')
28	  public async probe(
29	    @Query('marker') marker: string | undefined,
30	    @Query('consumerValue') consumerValue: string | undefined,
31	    @Query('delayMs') delayMs: string | undefined,
32	    @Query('fail') fail: string | undefined,
33	    @Query('registrations') registrations: string | undefined,
34	    @Query('failCallbackIndex') failCallbackIndex: string | undefined,
35	    @RequestContext() context: RequestContextSnapshot | undefined,
36	    @Req() request: any,
37	  ): Promise<{
38	    contextId: string;
39	    callbackIds: string[];
40	    aborted?: boolean;
41	  }> {
42	    if (!context) {
43	      throw new Error('Request context snapshot was not attached');
44	    }
45	    if (typeof marker !== 'string' || marker.length === 0) {
46	      throw new BadRequestException('marker query parameter is required');
47	    }
48	
49	    // Metadata extracted at the beginning of the request.
50	    context.set('marker', marker);
51	
52	    const count = clampRegistrations(registrations);
53	    const callbackIds: string[] = [];
54	    const failingIndex = parseOptionalIndex(failCallbackIndex);
55	
56	    for (let i = 0; i < count; i++) {
57	      const registrationIndex = i;
58	      const callbackId = context.registerAfterTerminated(
59	        async (snapshot: RequestContextSnapshot) => {
60	          try {
61	            // The callback body stays parked until the test releases the
62	            // gate (or shutdown releases every gate). Meanwhile the record
63	            // already reports "frozen", so the probe can distinguish
64	            // "terminated, callback waiting" from "callback completed".
65	            await this.records.waitForGate(callbackId);
66	
67	            if (fail === 'callback' || failingIndex === registrationIndex) {
68	              throw new Error(`intentional callback failure: ${marker}`);
69	            }
70	
71	            const firstRead = snapshot.get<string>('marker') ?? null;
72	            await Promise.resolve();
73	            const secondRead = snapshot.get<string>('marker') ?? null;
74	
75	            const lateWriteAccepted = snapshot.set('lateWrite', marker);
76	            const lateWriteVisible = snapshot.has('lateWrite');
77	            const thirdRead = snapshot.get<string>('marker') ?? null;
78	
79	            this.records.markCompleted(callbackId, {
80	              terminationReason: snapshot.getTerminationReason(),
81	              terminationCount: snapshot.getTerminationCount(),
82	              consumerValue: snapshot.get<string>('consumerValue') ?? null,
83	              frozenMarker: firstRead,
84	              lateWriteAccepted,
85	              lateWriteVisible,
86	              repeatedReadsConsistent:
87	                firstRead === marker &&
88	                secondRead === marker &&
89	                thirdRead === marker,
90	            });
91	          } catch (error) {
92	            // A failing callback only fails its own record; other callbacks
93	            // and other requests are untouched.
94	            this.records.markFailed(callbackId, error);
95	          }
96	        },
97	      );
98	
99	      // Every registration is an independent record, even for repeated or
100	      // identical markers.
101	      this.records.register(context.id, callbackId, marker);
102	      // Freeze observer (a microtask once terminate resolves waiters) runs
103	      // before the callback, which is scheduled with setImmediate.
104	      void context.whenFrozen().then(() => {
105	        this.records.markFrozen(callbackId, context);
106	      });
107	      callbackIds.push(callbackId);
108	    }
109	
110	    // A different consumer of the same request writes after the callbacks
111	    // were registered but still before termination: callbacks must observe
112	    // this value, registration order notwithstanding.
113	    if (consumerValue !== undefined) {
114	      context.set('consumerValue', consumerValue);
115	    }
116	
117	    if (fail === 'request') {
118	      throw new BadRequestException('intentional controller failure');
119	    }
120	
121	    if (fail === 'filtered') {
122	      throw new FilteredProbeError(marker);
123	    }
124	
125	    if (delayMs !== undefined) {
126	      const aborted = await waitForCompletionOrAbort(
127	        request,
128	        Number.parseInt(delayMs, 10) || 0,
129	      );
130	      if (aborted) {
131	        // The client went away; the raw response 'close' listener owned by
132	        // RequestContextHost has already terminated the snapshot as 'abort'.
133	        return { contextId: context.id, callbackIds, aborted: true };
134	      }
135	    }
136	
137	    return { contextId: context.id, callbackIds };
138	  }
139	
140	  @Get('context-records')
141	  public list() {
142	    return { records: this.records.getAll() };
143	  }
144	
145	  @Get('release-gates')
146	  public releaseGates(@Query('callbackId') callbackId?: string) {
147	    if (callbackId) {
148	      this.records.releaseGate(callbackId);
149	    } else {
150	      this.records.releaseAllGates();
151	    }
152	    return { released: true };
153	  }
154	
155	  @Get('health')
156	  public health() {
157	    return { status: 'ok' };
158	  }
159	}
160	
161	function clampRegistrations(registrations: string | undefined): number {
162	  const parsed = Number.parseInt(registrations ?? '1', 10);
163	  if (!Number.isFinite(parsed) || parsed < 1) {
164	    return 1;
165	  }
166	  return Math.min(parsed, 10);
167	}
168	
169	function parseOptionalIndex(value: string | undefined): number | undefined {
170	  if (value === undefined) {
171	    return undefined;
172	  }
173	  const parsed = Number.parseInt(value, 10);
174	  return Number.isFinite(parsed) ? parsed : undefined;
175	}
176	
177	/**
178	 * Resolves `true` when the underlying request socket closes before `ms`
179	 * elapses (client aborted), `false` on a normal timeout. Works with the
180	 * Express request (an `IncomingMessage`) and the Fastify request wrapper
181	 * (which exposes the raw message as `raw`).
182	 */
183	function waitForCompletionOrAbort(request: any, ms: number): Promise<boolean> {
184	  const rawRequest = request?.raw ?? request;
185	  return new Promise<boolean>(resolve => {
186	    let settled = false;
187	    const onClose = () => {
188	      if (settled) {
189	        return;
190	      }
191	      settled = true;
192	      clearTimeout(timer);
193	      resolve(true);
194	    };
195	    const timer = setTimeout(() => {
196	      if (settled) {
197	        return;
198	      }
199	      settled = true;
200	      rawRequest.removeListener?.('close', onClose);
201	      resolve(false);
202	    }, ms);
203	    rawRequest.once?.('close', onClose);
204	  });
205	}

1	import { Injectable, OnModuleDestroy } from '@nestjs/common';
2	
3	/**
4	 * Lifecycle of a single probe registration, as observed through
5	 * `/context-records`:
6	 *
7	 * - `active`    - the request has not terminated yet (snapshot still mutable).
8	 * - `frozen`    - the request terminated (snapshot frozen) but the callback
9	 *                 has not produced its result yet.
10	 * - `completed` - the callback finished reading the frozen snapshot.
11	 * - `failed`    - the callback failed; the error message was captured.
12	 */
13	export type ProbeRecordStatus = 'active' | 'frozen' | 'completed' | 'failed';
14	
15	export interface ProbeRecord {
16	  contextId: string;
17	  callbackId: string;
18	  marker: string;
19	  status: ProbeRecordStatus;
20	  terminationReason: 'finish' | 'abort' | null;
21	  terminationCount: number | null;
22	  consumerValue: string | null;
23	  frozenMarker: string | null;
24	  lateWriteAccepted: boolean | null;
25	  lateWriteVisible: boolean | null;
26	  repeatedReadsConsistent: boolean | null;
27	  errorMessage: string | null;
28	  registeredAt: number;
29	}
30	
31	interface Gate {
32	  promise: Promise<void>;
33	  release: () => void;
34	}
35	
36	function createGate(): Gate {
37	  let release: () => void = () => {};
38	  const promise = new Promise<void>(resolve => {
39	    release = resolve;
40	  });
41	  return { promise, release };
42	}
43	
44	/**
45	 * Application-scoped, in-memory store of probe records. It is a regular
46	 * singleton provider, so every bootstrapped application gets an independent
47	 * store: recreating the application can never replay or inherit records.
48	 */
49	@Injectable()
50	export class ContextRecordsStore implements OnModuleDestroy {
51	  private readonly records = new Map<string, ProbeRecord>();
52	  private readonly order: string[] = [];
53	  private readonly gates = new Map<string, Gate>();
54	
55	  public register(
56	    contextId: string,
57	    callbackId: string,
58	    marker: string,
59	  ): ProbeRecord {
60	    const record: ProbeRecord = {
61	      contextId,
62	      callbackId,
63	      marker,
64	      status: 'active',
65	      terminationReason: null,
66	      terminationCount: null,
67	      consumerValue: null,
68	      frozenMarker: null,
69	      lateWriteAccepted: null,
70	      lateWriteVisible: null,
71	      repeatedReadsConsistent: null,
72	      errorMessage: null,
73	      // Tie-break so insertion ordering is total even within one tick.
74	      registeredAt: Date.now() + this.order.length / 1000,
75	    };
76	    this.records.set(callbackId, record);
77	    this.order.push(callbackId);
78	    this.gates.set(callbackId, createGate());
79	    return record;
80	  }
81	
82	  public markFrozen(
83	    callbackId: string,
84	    snapshot: {
85	      getTerminationReason(): ProbeRecord['terminationReason'];
86	      getTerminationCount(): number;
87	    },
88	  ): void {
89	    const record = this.records.get(callbackId);
90	    if (record && record.status === 'active') {
91	      record.status = 'frozen';
92	      record.terminationReason = snapshot.getTerminationReason();
93	      record.terminationCount = snapshot.getTerminationCount();
94	    }
95	  }
96	
97	  public markCompleted(
98	    callbackId: string,
99	    payload: Pick<
100	      ProbeRecord,
101	      | 'terminationReason'
102	      | 'terminationCount'
103	      | 'consumerValue'
104	      | 'frozenMarker'
105	      | 'lateWriteAccepted'
106	      | 'lateWriteVisible'
107	      | 'repeatedReadsConsistent'
108	    >,
109	  ): void {
110	    const record = this.records.get(callbackId);
111	    if (!record) {
112	      return;
113	    }
114	    Object.assign(record, payload, { status: 'completed' as const });
115	  }
116	
117	  public markFailed(callbackId: string, error: unknown): void {
118	    const record = this.records.get(callbackId);
119	    if (!record) {
120	      return;
121	    }
122	    record.status = 'failed';
123	    record.errorMessage =
124	      error instanceof Error ? error.message : String(error);
125	  }
126	
127	  public waitForGate(callbackId: string): Promise<void> {
128	    return this.gates.get(callbackId)?.promise ?? Promise.resolve();
129	  }
130	
131	  public releaseGate(callbackId: string): void {
132	    this.gates.get(callbackId)?.release();
133	  }
134	
135	  public releaseAllGates(): void {
136	    this.gates.forEach(gate => gate.release());
137	  }
138	
139	  /**
140	   * Safety net for shutdown: never let a parked gate delay application
141	   * close. Runs before the HTTP adapter is disposed, so the request-context
142	   * shutdown drain that follows can await the now-unblocked callbacks.
143	   */
144	  public onModuleDestroy(): void {
145	    this.releaseAllGates();
146	  }
147	
148	  public getAll(): ProbeRecord[] {
149	    return this.order.map(id => this.records.get(id)!);
150	  }
151	}

